import os,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G), {k:(len(v),len(v[0])) for k,v in G.items()})

def transform(g):
    H,W=len(g),len(g[0]); out=[r[:] for r in g]
    seen=[[False]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            c=g[i][j]
            if c==0 or seen[i][j]: continue
            # bounding box of connected component? better: find rectangle of color c
            cells=[(i,j)]; seen[i][j]=True; k=0
            while k<len(cells):
                y,x=cells[k]; k+=1
                for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and g[ny][nx]==c:
                        seen[ny][nx]=True; cells.append((ny,nx))
            ys=[p[0] for p in cells]; xs=[p[1] for p in cells]
            r0,r1,c0,c1=min(ys),max(ys),min(xs),max(xs)
            h=r1-r0+1; w=c1-c0+1
            if len(cells)==2*(h+w)-4 and h>=3 and w>=3:  # hollow rectangle
                ih,iw=h-2,w-2
                fill=2 if (ih*iw)%2==0 else 7
                for y in range(r0+1,r1):
                    for x in range(c0+1,c1):
                        out[y][x]=fill
    return out

for k in sorted(G):
    if k.startswith('Demo pair') and k.endswith('input'):
        n=k.split()[2]
        ok = transform(G[k])==G['Demo pair %s output'%n]
        print(k, ok)
print(json.dumps(transform(G['Test input'])))
